-- Gold Query
SELECT T1.name FROM cards AS T1 INNER JOIN sets AS T2 ON T2.code = T1.setCode WHERE T2.name = 'Coldsnap' ORDER BY T1.convertedManaCost DESC, T1.id NULLS LAST, T2.id NULLS LAST LIMIT 1;

/*
Gold Result:
('Kari Nelson',)
*/

-- Prediction Query
SELECT cards.name FROM sets INNER JOIN cards ON sets.code = cards.setCode WHERE sets.name = 'Coldsnap' ORDER BY cards.convertedManaCost DESC, sets.id NULLS LAST, cards.id NULLS LAST LIMIT 1;

